"""Demo: detect polarization and recover the similitude weight of a weight multiset."""
from collections import Counter
from typing import List, Optional

def candidate_center(weights: List[int]) -> Optional[int]:
    if not weights:
        return None
    return min(weights) + max(weights)

def is_polarized(weights: List[int], c: int) -> bool:
    return Counter(weights) == Counter(c - a for a in weights)

def detect(weights: List[int]) -> Optional[int]:
    """Return the unique similitude weight c if the multiset is polarized, else None."""
    c = candidate_center(weights)
    if c is None:
        return None
    return c if is_polarized(weights, c) else None

if __name__ == "__main__":
    for W in ([2, 5, 8], [1, 6, 2, 5], [1, 2, 3, 5], [-4, 0, 4]):
        c = detect(W)
        print(f"W={sorted(W)} -> {'polarized, c=' + str(c) if c is not None else 'not polarized'}")

"""Demo: verify the purity identity 2*det(W) = c*n across random polarized families."""
import random
from typing import List

def make_polarized(half: List[int], c: int, central: bool) -> List[int]:
    """Build a polarized multiset from half the weights, optionally adding a central weight."""
    W = list(half) + [c - a for a in half]
    if central:
        assert c % 2 == 0
        W.append(c // 2)
    return sorted(W)

def purity_holds(W: List[int], c: int) -> bool:
    return 2 * sum(W) == c * len(W)

if __name__ == "__main__":
    random.seed(1)
    for _ in range(6):
        c = 2 * random.randint(-5, 5)
        half = random.sample(range(-9, 10), 3)
        central = random.choice([True, False])
        W = make_polarized(half, c, central)
        print(f"W={W}, c={c}, n={len(W)}: 2*det={2*sum(W)}, c*n={c*len(W)}, "
              f"purity={purity_holds(W, c)}")

"""Demo: extract the forced central Hodge-Tate weight in odd regular polarized data."""
from typing import List, Optional

def is_regular(weights: List[int]) -> bool:
    return len(set(weights)) == len(weights)

def central_weight(weights: List[int], c: int) -> Optional[int]:
    for a in weights:
        if 2 * a == c:
            return a
    return None

if __name__ == "__main__":
    cases = [([2, 5, 8], 10), ([1, 3, 5, 7, 9], 10), ([-6, -1, 2, 5, 10], 4)]
    for W, c in cases:
        assert is_regular(W) and len(W) % 2 == 1
        a = central_weight(W, c)
        print(f"W={sorted(W)}, c={c}: central a={a} (2a={2*a if a is not None else None})")

